<script lang="ts">import type { Snippet } from 'svelte'; import DialogPopup, { type DialogPopupProps } from '../dialog/DialogPopup.svelte'; import { getDrawerContext } from './drawer-context.svelte.js'; interface Props extends DialogPopupProps { children?: Snippet; } let { children, ref = $bindable(null), style, onpointerdown, ...rest }: Props = $props(); const drawer = getDrawerContext(); let dragging = $state(false); function start(event: PointerEvent) { onpointerdown?.(event as PointerEvent & { currentTarget: EventTarget & HTMLDivElement }); if (event.defaultPrevented || !(event.currentTarget instanceof HTMLElement) || (event.target instanceof Element && event.target.closest('button,a,input,select,textarea'))) return; const node = event.currentTarget; const startX = event.clientX; const startY = event.clientY; const size = drawer.swipeDirection === 'left' || drawer.swipeDirection === 'right' ? node.offsetWidth : node.offsetHeight; node.setPointerCapture?.(event.pointerId); dragging = true; const move = (e: PointerEvent) => { const raw = drawer.swipeDirection === 'down' ? e.clientY - startY : drawer.swipeDirection === 'up' ? startY - e.clientY : drawer.swipeDirection === 'right' ? e.clientX - startX : startX - e.clientX; drawer.swipeProgress = Math.max(0, Math.min(1, raw / Math.max(1, size))); }; const end = (e: PointerEvent) => { dragging = false; if (drawer.swipeProgress > 0.35) drawer.setOpen(false, e, 'swipe'); drawer.swipeProgress = 0; node.removeEventListener('pointermove', move); node.removeEventListener('pointerup', end); node.removeEventListener('pointercancel', end); }; node.addEventListener('pointermove', move); node.addEventListener('pointerup', end); node.addEventListener('pointercancel', end); } let popupStyle = $derived(`--drawer-swipe-progress:${drawer.swipeProgress};${typeof style === 'string' ? style : ''}`);</script>
<DialogPopup {...rest} bind:ref style={popupStyle} data-swipe-direction={drawer.swipeDirection} data-dragging={dragging ? '' : undefined} onpointerdown={start}>{@render children?.()}</DialogPopup>
